contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public entry point for the property test
    // params: caller (simulated by sending calls from this contract with different toOwner flag),
    // amount to send to contract to increase its balance and depositsCount via receive(),
    // withdrawAmount to attempt withdrawing from c.
    function run(bool asOwner, uint sendAmount, uint withdrawAmount) public payable {
        // this contract deployed C, so deployer == address(this) at C construction time? Actually C's owner is msg.sender at its deployment.
        // The checker deploys a fresh C and then passes it to this test's constructor, so deployer holds address(this) at construction.
        // We don't require anything on params.
        require(address(this).balance >= sendAmount, "insufficient test contract balance for sendAmount");

        // Record before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c to trigger receive and increment depositsCount
        // This call is a top-level state-changing call
        c.f{value: sendAmount}();

        // After send, depositsCount should have increased by either 0 or 1 depending on whether the receive executed.
        // But receive increments unconditionally when called with value, so we read after values now.
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Ensure that when we sent Ether, the contract balance increased by sendAmount and depositsCount increased by 1.
        // We will capture revert behavior of withdraw by trying both as owner and non-owner.

        bool withdrewReverted;
        uint balanceAfterWithdrawAttempt;

        // Simulate calls as owner or non-owner by using the fact that this contract was the deployer of C.
        // If asOwner==true, call withdraw from this contract (which is the owner). Otherwise, attempt to call withdraw
        // from a non-owner by using a low-level call that sets msg.sender to this contract's address as well —
        // but we cannot change msg.sender of calls; however the checker runs run() with msg.sender being external address.
        // To simulate non-owner, we rely on the external caller's address: when run is called, msg.sender may be different
        // from the original deployer. So we define that if asOwner==true we perform withdrawAll via c.withdrawAll(),
        // otherwise we call withdrawAll via a low-level call that will have the same msg.sender (the external caller),
        // but the only way to produce a non-owner caller is when the external caller != deployer. We capture revert.

        // Try calling withdrawAll and record if it reverts.
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        balanceAfterWithdrawAttempt = address(c).balance;

        // General rule to assert: If the caller of withdrawAll was the owner (i.e., the deployer of C), then the call must not revert and
        // contract balance must have decreased by the withdrawn amount (so balanceAfterWithdrawAttempt <= afterBalance).
        // If the caller was not the owner, the call must revert and the contract balance must remain unchanged.
        // We observe ownership by comparing tx.origin/deployer? We can observe owner via c.owner().

        address owner = c.owner();
        // msg.sender of this run() is the external caller; the actual withdrawAll call was made from this contract and so msg.sender for c.withdrawAll() is this contract.
        // Therefore withdrawAll succeeds iff this contract is the owner. That is, owner == address(this) implies no revert.

        bool thisIsOwner = (owner == address(this));

        // Assert the general invariant relating owner, revert flag, and balances
        assert(
            // If this contract is owner then withdrawAll did not revert and contract balance did not increase (it should stay <= afterBalance)
            ((thisIsOwner && !withdrewReverted && balanceAfterWithdrawAttempt <= afterBalance) ||
            // If this contract is not owner then withdrawAll must have reverted and contract balance stayed exactly the same
            (!thisIsOwner && withdrewReverted && balanceAfterWithdrawAttempt == afterBalance))
        );
    }

    // allow receiving Ether back from c when withdraw succeeds
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to send to C (to trigger receive), withdrawAttempt flag unused but kept for fuzzing
    function run(uint sendAmount, bool /*withdrawAttempt*/) public payable {
        // ensure we have funds to send
        require(address(this).balance >= sendAmount, "insufficient balance");

        // record before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c to trigger receive() and increment depositsCount
        // This is a top-level state-changing call
        (bool ok, ) = address(c).call{value: sendAmount}("");
        // The receive() can revert (if overflow in depositsCount would occur), capture that
        bool sendReverted = !ok;

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt withdrawAll and record whether it reverts and balance after
        bool withdrawReverted;
        try c.withdrawAll() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint finalBalance = address(c).balance;

        // Observe owner
        address owner = c.owner();
        bool thisIsOwner = (owner == address(this));

        // General rule (single assert):
        // 1) The send behavior: if the low-level send did not revert then afterBalance == beforeBalance + sendAmount
        //    and afterDeposits == beforeDeposits + 1. If it reverted then balances/counts unchanged.
        // 2) The withdrawAll behavior: if this contract is owner then withdrawAll must not revert and finalBalance <= afterBalance
        //    (funds moved out); if not owner then withdrawAll must revert and finalBalance == afterBalance.
        assert(
            (
                // send succeeded case
                (!sendReverted && afterBalance == beforeBalance + sendAmount && afterDeposits == beforeDeposits + 1)
                ||
                // send reverted case
                (sendReverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            )
            &&
            (
                // owner case: withdraw did not revert and balance decreased or stayed <= (transfer may be 0)
                (thisIsOwner && !withdrawReverted && finalBalance <= afterBalance)
                ||
                // non-owner case: withdraw reverted and balance unchanged
                (!thisIsOwner && withdrawReverted && finalBalance == afterBalance)
            )
        );
    }

    // allow receiving Ether from C when withdraw succeeds
    receive() external payable {}
}

