    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint depositValue, uint opValue, address payable target) public payable {
        require(true);

        // If depositValue > 0, send Ether to c to trigger receive() and increment depositsCount
        if (depositValue > 0) {
            require(address(this).balance >= depositValue);
            // top-level state-changing call to c: send Ether to trigger receive()
            (bool ok,) = address(c).call{value: depositValue}("");
            // ignore ok here; receive might revert in some bad implementations but that's allowed
        }

        // Read observable before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        address ownerAddr = c.owner();

        // Attempt withdraw (top-level call). Record whether it reverted.
        bool withdrawReverted;
        try c.withdraw(opValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt sendMoney (top-level call). Record whether it reverted.
        bool sendReverted;
        try c.sendMoney(target, opValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // Read observable after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;

