        assert(
            // depositsCount never decreases
            afterDeposits >= beforeDeposits
            // and C's balance never increases as a result of withdraw/sendMoney attempts
            && afterBalanceC <= beforeBalanceC
            // Additionally, if this contract is not the owner then both owner-only calls must revert and state unchanged
            && (ownerAddr == address(this) ? true : (withdrawReverted && sendReverted && afterDeposits == beforeDeposits && afterBalanceC == beforeBalanceC))
        );
