contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint depositValue, uint withdrawValue, address payable sendTarget) public payable {
        require(true);

        // If depositValue > 0, top-level state-changing call: send Ether to c to trigger receive()
        if (depositValue > 0) {
            require(address(this).balance >= depositValue);
            // top-level call: low-level send to trigger receive()
            (bool ok,) = address(c).call{value: depositValue}("");
            // we do not revert here; ok may be false if receive() reverts
        }

        // Observe before-values (view calls allowed here)
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        address ownerAddr = c.owner();

